SELECT Федеральные_округа.name AS Fed_okr, [Станции_для_сводной(архив)].nameoes, [Станции_для_сводной(архив)].oblname, [Станции_для_сводной(архив)].NAME, [Станции_для_сводной(архив)].Year, [Станции_для_сводной(архив)].nust, IIf([W]>0,[W],0) AS W_en, IIf([Qotp]>0,[Qotp],0) AS Teplo, [Выбросы ЗВ].VIBROS_ekol, [Выбросы ЗВ].TVERD_V, [Выбросы ЗВ].[GAZ and ZHID], [Выбросы ЗВ].SO2_gaz, [Выбросы ЗВ].CO_gaz, [Выбросы ЗВ].NOx_gaz, [Выбросы ЗВ].UGLEVOD, [Выбросы ЗВ].LOS, [Выбросы ЗВ].PROCH_ekol, IIf([Ведомство]=1,"МинЭн","Пром.предпр.") AS BLST, ([gaz_est]+[gaz_isk])*1000 AS GAZ_6tp, [gaz_est]*1000 AS GAZ_estestv, IIf([MAZUT]>0,[MAZUT]*1000,0) AS MAZUT_6tp, ([ugol_6tp]+[torf_6tp]+[proch_tverd])*1000 AS TVERD_TOPL_6tp, [Станции_для_сводной(архив)].numb1120, [TVERD_V]+[SO2_gaz]+[NOx_gaz] AS ZV_normir, [W_en]+[Teplo]/859.8*1000 AS energy, IIf([MAZUT_6tp]>0 Or [TVERD_TOPL_6tp]>0,[TVERD_V]/([MAZUT_6tp]+[TVERD_TOPL_6tp])*1000,0) AS udel_tv, IIf([MAZUT_6tp]>0 Or [TVERD_TOPL_6tp]>0,[SO2_gaz]/([MAZUT_6tp]+[TVERD_TOPL_6tp])*1000,0) AS udel_SO2, IIf([MAZUT_6tp]>0 Or [TVERD_TOPL_6tp]>0 Or [GAZ_6tp]>0,[NOx_gaz]/([GAZ_6tp]+[MAZUT_6tp]+[TVERD_TOPL_6tp])*1000,0) AS udel_NOx, IIf([energy]>0,[VIBROS_ekol]/[energy],0) AS udel_na_energ, IIf([energy]>0,[ZV_normir]/[energy]) AS normir_ZV_na_energ, IIf([energy]>0,[TVERD_V]/[energy]) AS normir_TVERD_na_energ, IIf([energy]>0,[SO2_gaz]/[energy]) AS normir_SO2_na_energ, IIf([energy]>0,[NOx_gaz]/[energy]) AS normir_NOx_na_energ, [Станции_для_сводной(архив)].obor
FROM ((([Станции_для_сводной(архив)] LEFT JOIN [Выбросы ЗВ] ON ([Станции_для_сводной(архив)].Year = [Выбросы ЗВ].year) AND ([Станции_для_сводной(архив)].NUMB1120 = [Выбросы ЗВ].numb1120)) INNER JOIN Имена_станций ON [Станции_для_сводной(архив)].numb1120 = Имена_станций.NUMB) INNER JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) INNER JOIN Федеральные_округа ON [Станции_для_сводной(архив)].FO = Федеральные_округа.fo
WHERE ((([Станции_для_сводной(архив)].Year)>2016) AND (([Станции_для_сводной(архив)].group)=0 Or ([Станции_для_сводной(архив)].group) Is Null))
ORDER BY [Станции_для_сводной(архив)].numb1, [Станции_для_сводной(архив)].Year;
